#[using="Type"] Lemma byte_of_range : forall x k, 0 <= byte_of x k < 256.
Proof.
  intros x k. unfold byte_of. split; [apply Z.land_nonneg; right; lia|].
  change 255 with (Z.ones 8). rewrite Z.land_ones by lia. apply Z.mod_pos_bound. lia.
Qed.

