            n P (conc st mt) (r_base r + snd bm) (conc st (area_of mt)) EE (P + n) stride res
            (i + 32 * Z.min res 5) q (m_avail mr) (m_freed mr) (m_last_idx mr) (m_freeable mr) (m_sizeclass mr) (m_maplen mr)
